  sealed class PluginHost : IAwlPluginHost {
   readonly Shell shell;readonly InstalledPlugin plugin;
   public PluginHost(Shell owner,InstalledPlugin value){shell=owner;plugin=value;}
   public string DataRoot {get{string path=Path.Combine(shell.PluginFolder,"Data",plugin.Manifest.id);Directory.CreateDirectory(path);return path;}}
   public void RegisterTab(AwlPluginTab tab){if(tab==null||String.IsNullOrWhiteSpace(tab.Id)||tab.Build==null)throw new ArgumentException("Plugin tabs need an id and Build callback.");if(String.IsNullOrWhiteSpace(tab.Icon))tab.Icon=plugin.Manifest.icon;shell.pluginTabs[plugin.Manifest.id+":"+tab.Id]=tab;}
   public void RegisterSection(AwlPluginSection section){if(section==null||String.IsNullOrWhiteSpace(section.Id)||String.IsNullOrWhiteSpace(section.Tab)||section.Build==null)throw new ArgumentException("Plugin sections need an id, target tab, and Build callback.");if(String.IsNullOrWhiteSpace(section.Icon))section.Icon=plugin.Manifest.icon;shell.pluginSections[plugin.Manifest.id+":"+section.Id]=section;}
   public void RegisterToolbarAction(AwlPluginAction action){if(action==null||String.IsNullOrWhiteSpace(action.Id)||action.Execute==null)throw new ArgumentException("Toolbar actions need an id and callback.");string key=plugin.Manifest.id+":"+action.Id;shell.pluginToolbarActions[key]=action;if(!shell.cfg.ModuleOrder.Contains(key))shell.cfg.ModuleOrder.Add(key);}
   public void RegisterAction(AwlPluginAction action){if(action==null||String.IsNullOrWhiteSpace(action.Id)||action.Execute==null)throw new ArgumentException("Actions need an id and callback.");shell.pluginActions[plugin.Manifest.id+":"+action.Id]=action;}
   public void RegisterCalculator(AwlPluginCalculator calculator){if(calculator==null||String.IsNullOrWhiteSpace(calculator.Id)||calculator.Evaluate==null)throw new ArgumentException("Calculators need an id and evaluator.");shell.pluginCalculators[plugin.Manifest.id+":"+calculator.Id]=calculator;}
   public void RegisterService(string id,object service){if(String.IsNullOrWhiteSpace(id)||service==null)throw new ArgumentException("Services need an id and instance.");if(shell.pluginServices.ContainsKey(id))throw new InvalidOperationException("A plugin service is already registered as "+id+".");shell.pluginServices[id]=service;}
   public object GetService(string id){object service;return String.IsNullOrWhiteSpace(id)||!shell.pluginServices.TryGetValue(id,out service)?null:service;}
   public void Launch(string target){shell.Dispatcher.BeginInvoke(new Action(()=>shell.Launch(target)));}
   public void Log(string message){Shell.Log("Plugin "+plugin.Manifest.id+": "+message);}
  }

  void LoadPlugins(){if(pluginsLoaded)return;pluginsLoaded=true;ResetVisualMotion();signature="";Directory.CreateDirectory(InstalledPluginFolder);ApplyPendingPluginUpdates();installedPlugins.Clear();pluginTabs.Clear();pluginSections.Clear();pluginToolbarActions.Clear();pluginActions.Clear();pluginCalculators.Clear();pluginServices.Clear();pluginServices["awl.layout-ratio-api"]=new LayoutRatioService(this);pluginVisualTokens.Clear();foreach(string folder in Directory.GetDirectories(InstalledPluginFolder).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase)){InstalledPlugin plugin=null;try{if(File.Exists(Path.Combine(folder,"remove.on.restart"))){Directory.Delete(folder,true);continue;}string manifestFile=Path.Combine(folder,"manifest.json");if(!File.Exists(manifestFile))continue;var manifest=new JavaScriptSerializer().Deserialize<AwlPluginManifest>(File.ReadAllText(manifestFile));ValidatePluginManifest(manifest);plugin=new InstalledPlugin{Manifest=manifest,Folder=folder,Enabled=cfg.EnabledPlugins.Contains(manifest.id,StringComparer.OrdinalIgnoreCase)};installedPlugins.Add(plugin);if(!plugin.Enabled)continue;if(PluginHasVisual(manifest)){LoadPluginStyle(plugin);LoadVisualMotion(plugin);}if(PluginHasCore(manifest)){LoadManifestActions(plugin);LoadCorePlugin(plugin);}plugin.Loaded=true;}catch(Exception error){if(plugin!=null)plugin.Error=error.Message;Log("Plugin load: "+error);}}}
  bool PluginHasCore(AwlPluginManifest manifest){return manifest.type.Equals("Core",StringComparison.OrdinalIgnoreCase)||manifest.type.Equals("Both",StringComparison.OrdinalIgnoreCase);}
  bool PluginHasVisual(AwlPluginManifest manifest){return manifest.type.Equals("Visual",StringComparison.OrdinalIgnoreCase)||manifest.type.Equals("Both",StringComparison.OrdinalIgnoreCase);}
  void ValidatePluginManifest(AwlPluginManifest manifest){if(manifest==null||!String.Equals(manifest.format,"Awl Plugin",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("This package is not an Awl plugin.");if(!Regex.IsMatch(manifest.id??"",@"^[a-z0-9][a-z0-9._-]{2,63}$",RegexOptions.IgnoreCase))throw new InvalidDataException("Plugin id must contain 3–64 letters, numbers, dots, dashes, or underscores.");if(!new[]{"Core","Visual","Both"}.Contains(manifest.type,StringComparer.OrdinalIgnoreCase))throw new InvalidDataException("Plugin type must be Core, Visual, or Both.");manifest.categories=manifest.categories??new List<string>();manifest.tags=manifest.tags??new List<string>();manifest.actions=manifest.actions??new List<AwlPluginManifestAction>();if(PluginHasCore(manifest)&&String.IsNullOrWhiteSpace(manifest.entryAssembly)&&manifest.actions.Count==0)throw new InvalidDataException("Core plugins must declare entryAssembly or at least one script action.");}
  void LoadCorePlugin(InstalledPlugin plugin){if(String.IsNullOrWhiteSpace(plugin.Manifest.entryAssembly))return;string entry=devMode&&!String.IsNullOrWhiteSpace(plugin.Manifest.entryAssemblyDevMode)?plugin.Manifest.entryAssemblyDevMode:plugin.Manifest.entryAssembly;string assemblyFile=SafePluginFile(plugin.Folder,entry);if(!File.Exists(assemblyFile))throw new FileNotFoundException("Core plugin assembly was not found.",assemblyFile);var assembly=Assembly.LoadFrom(assemblyFile);IEnumerable<Type> candidates=assembly.GetTypes().Where(t=>typeof(IAwlCorePlugin).IsAssignableFrom(t)&&!t.IsAbstract&&!t.IsInterface);if(!String.IsNullOrWhiteSpace(plugin.Manifest.entryType))candidates=candidates.Where(t=>String.Equals(t.FullName,plugin.Manifest.entryType,StringComparison.Ordinal));var type=candidates.FirstOrDefault();if(type==null)throw new InvalidDataException("No IAwlCorePlugin entry type was found.");var instance=(IAwlCorePlugin)Activator.CreateInstance(type);instance.Initialize(new PluginHost(this,plugin));}
  void LoadManifestActions(InstalledPlugin plugin){foreach(var declared in plugin.Manifest.actions){if(declared==null||String.IsNullOrWhiteSpace(declared.id)||String.IsNullOrWhiteSpace(declared.target))continue;var action=declared;Action run=()=>RunPluginTarget(plugin,action);var registered=new AwlPluginAction{Id=action.id,Title=action.title,Description=action.description,Execute=run};string key=plugin.Manifest.id+":"+action.id;if(String.Equals(action.placement,"Toolbar",StringComparison.OrdinalIgnoreCase)){pluginToolbarActions[key]=registered;if(!cfg.ModuleOrder.Contains(key))cfg.ModuleOrder.Add(key);}else pluginActions[key]=registered;}}
  void RunPluginTarget(InstalledPlugin plugin,AwlPluginManifestAction action){string target=action.target;if(!Uri.IsWellFormedUriString(target,UriKind.Absolute))target=SafePluginFile(plugin.Folder,target);if(target.EndsWith(".ps1",StringComparison.OrdinalIgnoreCase)){Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+target+"\" "+(action.arguments??"")){UseShellExecute=false});return;}Process.Start(new ProcessStartInfo(target,action.arguments??""){UseShellExecute=true});}
  string SafePluginFile(string root,string relative){string clean=(relative??"").Replace('/',Path.DirectorySeparatorChar);string full=Path.GetFullPath(Path.Combine(root,clean)),prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Unsafe path in plugin manifest.");return full;}
  void LoadPluginStyle(InstalledPlugin plugin){string file=SafePluginFile(plugin.Folder,String.IsNullOrWhiteSpace(plugin.Manifest.style)?"style.css":plugin.Manifest.style);if(!File.Exists(file))return;string css=Regex.Replace(File.ReadAllText(file),@"/\*.*?\*/","",RegexOptions.Singleline);foreach(Match match in Regex.Matches(css,@"--([a-zA-Z0-9_-]+)\s*:\s*([^;}{]+)\s*;"))pluginVisualTokens[match.Groups[1].Value.Trim()]=match.Groups[2].Value.Trim();}
  string VisualToken(string name,string fallback){string value;return pluginVisualTokens.TryGetValue(name,out value)?value:fallback;}
  double VisualNumber(string name,double fallback){double value;string text;if(!pluginVisualTokens.TryGetValue(name,out text))return fallback;text=text.Trim().TrimEnd('p','x','%');return Double.TryParse(text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)?value:fallback;}
  void ApplyVisualPluginTokens(){if(pluginVisualTokens.Count==0)return;baseColor=Parse(VisualToken("background",Hex(baseColor)),baseColor);var text=Parse(VisualToken("text",Hex((ink as SolidColorBrush).Color)),(ink as SolidColorBrush).Color);var accent=Parse(VisualToken("accent",Hex((accentBrush as SolidColorBrush).Color)),(accentBrush as SolidColorBrush).Color);ink=new SolidColorBrush(text);teal=new SolidColorBrush(baseColor);panelBrush=new SolidColorBrush(Parse(VisualToken("panel",Hex((panelBrush as SolidColorBrush).Color)),(panelBrush as SolidColorBrush).Color));cardBrush=new SolidColorBrush(Parse(VisualToken("card",Hex((cardBrush as SolidColorBrush).Color)),(cardBrush as SolidColorBrush).Color));mutedBrush=new SolidColorBrush(Parse(VisualToken("muted",Hex((mutedBrush as SolidColorBrush).Color)),(mutedBrush as SolidColorBrush).Color));accentBrush=new SolidColorBrush(accent);}

  void InstallPlugin(){
   var picker=new OpenFileDialog{Title="Install Awl plugin",Filter="Awl plugins (*.awlplugin;*.zip)|*.awlplugin;*.zip|All files|*.*"};if(picker.ShowDialog(launcher)!=true)return;
   try{AwlPluginManifest manifest;using(var zip=ZipFile.OpenRead(picker.FileName)){var entry=zip.GetEntry("manifest.json");if(entry==null)throw new InvalidDataException("The plugin has no manifest.json.");using(var reader=new StreamReader(entry.Open()))manifest=new JavaScriptSerializer().Deserialize<AwlPluginManifest>(reader.ReadToEnd());}ValidatePluginManifest(manifest);
    bool installed=installedPlugins.Any(p=>String.Equals(p.Manifest.id,manifest.id,StringComparison.OrdinalIgnoreCase));var expected=new AwlCatalogItem{id=manifest.id,version=manifest.version};bool restart=PrepareCatalogPlugin(picker.FileName,expected,out manifest);
    if(!installed&&!cfg.EnabledPlugins.Contains(manifest.id,StringComparer.OrdinalIgnoreCase))cfg.EnabledPlugins.Add(manifest.id);SaveConfig();pluginRestartRequired|=restart;if(!restart){pluginsLoaded=false;LoadPlugins();ApplyTheme();}if(PluginCatalogChanged!=null)PluginCatalogChanged();DrawLauncher();
   }catch(Exception error){MessageBox.Show(launcher,error.Message,"Plugin could not be installed");}
  }
  string LocalCatalogPackage(AwlCatalogItem item){
   string relative=item==null?"":item.downloadUrl??"";
   if(String.IsNullOrWhiteSpace(relative)||Uri.IsWellFormedUriString(relative,UriKind.Absolute))return "";
   string clean=relative.Replace('/',Path.DirectorySeparatorChar);
   foreach(string root in new[]{Path.Combine(DevProjectRoot(),"plugins"),Path.Combine(InstallRoot,"plugins")}){string candidate=Path.Combine(root,clean);if(File.Exists(candidate))return candidate;}
   return "";
  }
  string CatalogPackageUrl(AwlCatalogItem item){if(item==null||String.IsNullOrWhiteSpace(item.downloadUrl))return "";if(Uri.IsWellFormedUriString(item.downloadUrl,UriKind.Absolute))return item.downloadUrl;return "https://raw.githubusercontent.com/"+BuildInfo.Repository+"/main/plugins/"+item.downloadUrl.TrimStart('/');}
  ImageSource CatalogPackageImage(AwlCatalogItem item,string name,int decode=160){
   try{
    if(item==null||String.IsNullOrWhiteSpace(item.id)||String.IsNullOrWhiteSpace(name))return null;
    string installed=Path.Combine(InstalledPluginFolder,item.id,name);if(File.Exists(installed))return FileImage(installed,decode);
    string package=LocalCatalogPackage(item);if(String.IsNullOrWhiteSpace(package))return null;
    string cacheFolder=Path.Combine(PluginFolder,"CatalogImages");Directory.CreateDirectory(cacheFolder);string target=Path.Combine(cacheFolder,SafePluginFileName(item.id)+"-"+name);if(!File.Exists(target)||File.GetLastWriteTimeUtc(target)<File.GetLastWriteTimeUtc(package)){using(var zip=ZipFile.OpenRead(package)){var entry=zip.GetEntry(name);if(entry==null)return null;using(var input=entry.Open())using(var output=File.Create(target)){input.CopyTo(output);}}}return FileImage(target,decode);
   }catch{return null;}
  }
  string SafePluginFileName(string value){return Regex.Replace(value??"plugin",@"[^a-zA-Z0-9._-]","-");}
  void SetCatalogInstallProgress(Button button,double progress){if(button==null)return;var bar=button.Content as ProgressBar;if(bar==null){bar=new ProgressBar{Minimum=0,Maximum=100,Height=5,Width=54,Value=0,Foreground=accentBrush,Background=cardBrush,BorderThickness=new Thickness(0),IsHitTestVisible=false};button.Content=bar;button.Padding=new Thickness(6,7,6,7);button.IsEnabled=false;}bar.Value=Math.Max(0,Math.Min(100,progress));}
  async void InstallCatalogPlugin(AwlCatalogItem item,Action<double> progress=null,Action<bool> completed=null){
   if(!installingPluginIds.Add(item.id))return;bool wasInstalled=installedPlugins.Any(p=>String.Equals(p.Manifest.id,item.id,StringComparison.OrdinalIgnoreCase));string package=LocalCatalogPackage(item),temporary="";
   if(!String.IsNullOrWhiteSpace(package)&&!CatalogPackageMatches(package,item))package="";
   try{
    if(progress!=null)progress(0);
    if(String.IsNullOrWhiteSpace(package)){
     string url=CatalogPackageUrl(item);if(String.IsNullOrWhiteSpace(url))throw new InvalidDataException("This catalog item has no package URL.");
     temporary=Path.Combine(Path.GetTempPath(),"Awl-plugin-"+Guid.NewGuid().ToString("N")+".awlplugin");
     using(var client=new WebClient()){client.Headers.Add(HttpRequestHeader.UserAgent,"Awl/"+BuildInfo.Version);client.DownloadProgressChanged+=delegate(object sender,DownloadProgressChangedEventArgs e){if(progress!=null)progress(Math.Min(90,e.ProgressPercentage*.9));};await client.DownloadFileTaskAsync(new Uri(url),temporary);}
     package=temporary;
    }
    if(progress!=null)progress(94);AwlPluginManifest manifest;bool restart=PrepareCatalogPlugin(package,item,out manifest);if(!wasInstalled&&!cfg.EnabledPlugins.Contains(manifest.id,StringComparer.OrdinalIgnoreCase))cfg.EnabledPlugins.Add(manifest.id);SaveConfig();pluginRestartRequired|=restart;if(!restart){pluginsLoaded=false;LoadPlugins();ApplyTheme();}installingPluginIds.Remove(item.id);if(progress!=null)progress(100);if(completed!=null)completed(restart);if(PluginCatalogChanged!=null)PluginCatalogChanged();DrawLauncher();
   }catch(Exception error){installingPluginIds.Remove(item.id);if(progress!=null)progress(-1);MessageBox.Show(launcher,error.Message,"Plugin could not be installed");}
   finally{installingPluginIds.Remove(item.id);if(!String.IsNullOrWhiteSpace(temporary))try{File.Delete(temporary);}catch{}}
  }
  void RemovePlugin(InstalledPlugin plugin){try{if(installingPluginIds.Contains(plugin.Manifest.id))return;string pending=Path.Combine(PluginFolder,"Pending",plugin.Manifest.id);if(Directory.Exists(pending))Directory.Delete(pending,true);cfg.EnabledPlugins.RemoveAll(x=>String.Equals(x,plugin.Manifest.id,StringComparison.OrdinalIgnoreCase));SaveConfig();bool deferred=plugin.Loaded&&PluginHasCore(plugin.Manifest);if(deferred){File.WriteAllText(Path.Combine(plugin.Folder,"remove.on.restart"),DateTime.UtcNow.ToString("o"));pluginRestartRequired=true;}else Directory.Delete(plugin.Folder,true);installedPlugins.Remove(plugin);ResetVisualMotion();signature="";pluginVisualTokens.Clear();foreach(var remaining in installedPlugins.Where(x=>x.Enabled&&PluginHasVisual(x.Manifest))){LoadPluginStyle(remaining);LoadVisualMotion(remaining);}ApplyTheme();DrawLauncher();}catch(Exception error){MessageBox.Show(launcher,error.Message,"Plugin could not be removed");}}
  void SetPluginEnabled(InstalledPlugin plugin,bool enabled){plugin.Enabled=enabled;cfg.EnabledPlugins.RemoveAll(x=>String.Equals(x,plugin.Manifest.id,StringComparison.OrdinalIgnoreCase));if(enabled)cfg.EnabledPlugins.Add(plugin.Manifest.id);SaveConfig();if(PluginHasCore(plugin.Manifest))pluginRestartRequired=true;else{pluginsLoaded=false;LoadPlugins();ApplyTheme();}DrawLauncher();}
