  FrameworkElement PluginTypeBadge(string type){var color=type.Equals("Visual",StringComparison.OrdinalIgnoreCase)?new SolidColorBrush(Color.FromRgb(103,165,204)):new SolidColorBrush(Color.FromRgb(185,144,73));return new Border{Background=new SolidColorBrush(Color.FromArgb(40,((SolidColorBrush)color).Color.R,((SolidColorBrush)color).Color.G,((SolidColorBrush)color).Color.B)),CornerRadius=new CornerRadius(5),Padding=new Thickness(5,1,5,1),Child=Text(type.ToUpperInvariant(),8,color)};}
  void PluginConfigSection(){var updateCheck=CheckPluginUpdates();page.Children.Add(Card("",()=>{var header=new DockPanel{Margin=new Thickness(0,0,0,5)};var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};DockPanel.SetDock(actions,Dock.Right);var install=Action("",InstallPlugin);install.Content=BuilderIconLabel("download","Import plugin",install.Foreground,13);actions.Children.Add(install);var browse=Action("",()=>ShowPluginBrowser());browse.Content=BuilderIconLabel("search","Browse plugins",accentBrush,13);actions.Children.Add(browse);Button check=null;check=Action("Check updates",async ()=>{check.IsEnabled=false;check.Content="Checking…";await CheckPluginUpdates(true);check.IsEnabled=true;check.Content="Check updates";});check.IsEnabled=!pluginUpdateCheckBusy;check.Content=pluginUpdateCheckBusy?"Checking…":"Check updates";actions.Children.Add(check);header.Children.Add(actions);var title=new StackPanel();title.Children.Add(BuilderIconLabel("prefab","Plugins",ink,15));title.Children.Add(Text("core functionality & visual mods",11,mutedBrush));header.Children.Add(title);page.Children.Add(header);if(!String.IsNullOrEmpty(pluginUpdateStatus))page.Children.Add(Text(pluginUpdateStatus,10,mutedBrush));var note=Text("Core plugins can add new tabs, scripts, and button actions. Visual plugins only restyle Awl and other plugins.",10,mutedBrush);note.TextWrapping=TextWrapping.Wrap;note.Margin=new Thickness(0,0,0,8);page.Children.Add(note);if(installedPlugins.Count==0){if(pluginRestartRequired){page.Children.Add(Text("Plugins are ready to apply. Reload Awl to finish installation.",11,mutedBrush));page.Children.Add(PluginReloadButton());}else page.Children.Add(Text("No plugins installed. Browse the repository to find one.",11,mutedBrush));return;}foreach(var plugin in installedPlugins.OrderBy(x=>x.Manifest.name)){var item=plugin;var row=new DockPanel{Margin=new Thickness(0,7,0,0)};var toggle=pluginRestartRequired&&PluginHa