  AwlCatalog ReadPluginCatalog(){var catalog=new AwlCatalog();foreach(string file in new[]{Path.Combine(PluginFolder,"catalog.json"),Path.Combine(DevProjectRoot(),"plugins","catalog.json")})try{if(File.Exists(file)){catalog=new JavaScriptSerializer().Deserialize<AwlCatalog>(File.ReadAllText(file))??catalog;if(catalog.items==null)catalog.items=new List<AwlCatalogItem>();return catalog;}}catch(Exception error){Log("Plugin catalog: "+error.Message);}try{using(var stream=typeof(Shell).Assembly.GetManifestResourceStream("Awl.Plugins.catalog.json"))if(stream!=null)using(var reader=new StreamReader(stream)){catalog=new JavaScriptSerializer().Deserialize<AwlCatalog>(reader.ReadToEnd())??catalog;catalog.items=catalog.items??new List<AwlCatalogItem>();}}catch(Exception error){Log("Embedded plugin catalog: "+error.Message);}return catalog;}
