  IEnumerable<AwlCatalogItem> FilterCatalog(IEnumerable<AwlCatalogItem> items,string query,string type,IEnumerable<string> categories){var selected=new HashSet<string>(categories??new string[0],StringComparer.OrdinalIgnoreCase);query=(query??"").Trim();return (items??new AwlCatalogItem[0]).Where(item=>(String.IsNullOrWhiteSpace(type)||type=="All"||String.Equals(item.type,type,StringComparison.OrdinalIgnoreCase)||(type=="Both"&&String.Equals(item.type,"Both",StringComparison.OrdinalIgnoreCase)))&&(selected.Count==0||(item.categories??new List<string>()).Any(selected.Contains))&&(query.Length==0||(item.name+" "+item.summary+" "+String.Join(" ",item.tags??new List<string>())).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0));}
  void PluginTabPage(string key){AwlPluginTab tab;if(!pluginTabs.TryGetValue(key,out tab)){Header("Plugin unavailable");page.Children.Add(Text("This plugin tab is no longer registered.",12,mutedBrush));return;}Header(tab.Title,null,tab.Icon);try{var content=tab.Build();if(content!=null)page.Children.Add(content);}catch(Exception error){page.Children.Add(Text(error.Message,12,Brushes.IndianRed));Log("Plugin tab "+key+": "+error);}}  void AppendPluginSections(string tabName){foreach(var entry in pluginSections.OrderBy(x=>x.Key).Select(x=>x.Value).Where(x=>String.Equals(x.Tab,tabName,StringComparison.OrdinalIgnoreCase))){var section=entry;try{var content=section.Build();if(content==null)continue;page.Children.Add(Card("",()=>{var heading=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,10)};var icon=NavIcon(String.IsNullOrWhiteSpace(section.Icon)?"Config":section.Icon,ink,16,1.8);icon.Margin=new Thickness(0,0,8,0);heading.Children.Add(icon);var title=Text(section.Title,14);title.FontWeight=FontWeights.SemiBold;heading.Children.Add(title);page.Children.Add(heading);page.Children.Add(content);}));}catch(Exception error){Log("Plugin section "+section.Id+": "+error.Message);}}}
  string EvaluatePluginCalculation(string query){foreach(var calculator in pluginCalculators.Values)try{string value=calculator.Evaluate(query);if(!String.IsNullOrWhiteSpace(value))return value;}catch(Exception error){Log("Plugin calculator "+calculator.Id+": "+error.Message);}return null;}
  public string PluginSelfTest(){string folder=Path.Combine(Path.GetTempPath(),"Awl-plugin-test-"+Guid.NewGuid().ToString("N"));try{Directory.CreateDirectory(folder);var manifest=new AwlPluginManifest{id="test.visual",name="Test visual",type="Visual",description="Test",categories=new List<string>{"Appearance"}};ValidatePluginManifest(manifest);File.WriteAllText(Path.Combine(folder,"style.css"),":root { --background: #123456; --card-radius: 22px; }");var plugin=new InstalledPlugin{Manifest=manifest,Folder=folder,Enabled=true};LoadPluginStyle(plugin);if(VisualToken("background","")!="#123456"||Math.Abs(VisualNumber("card-radius",0)-22)>.01)return "FAILED: visual plugin tokens";bool rejected=false;try{SafePluginFile(folder,"../escape.dll");}catch(InvalidDataException){rejected=true;}if(!rejected)return "FAILED: plugin path traversal guard";var catalog=new[]{new AwlCatalogItem{name="Glass",type="Visual",summary="Glossy surfaces",categories=new List<string>{"Appearance"}},new AwlCatalogItem{name="Math",type="Core",summary="Calculations",categories=new List<string>{"Productivity"}}};if(FilterCatalog(catalog,"glass","Visual",new[]{"Appearance"}).Count()!=1)return "FAILED: catalog search filters";return "Plugin manifests, visual tokens, catalog filters, and package path guards passed";}catch(Exception error){return "FAILED: plugin system "+error.Message;}finally{try{Directory.Delete(folder,true);}catch{}}}
